-- supabase/migrations/20261124000100_initial_schema.sql
create extension if not exists pgcrypto;
create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null check(length(name) between 1 and 120), created_at timestamptz not null default now());
create table public.memberships (org_id uuid not null references public.organizations(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, role text not null check(role in ('owner','admin','analyst')), created_at timestamptz not null default now(), primary key(org_id,user_id));
create table public.locations (id uuid primary key default gen_random_uuid(), org_id uuid not null references public.organizations(id) on delete cascade, name text not null, city text not null default 'Sénégal', spot text not null default 'Accueil', active boolean not null default true, created_at timestamptz not null default now());
create table public.qr_codes (id uuid primary key default gen_random_uuid(), org_id uuid not null references public.organizations(id) on delete cascade, location_id uuid not null references public.locations(id) on delete cascade, label text not null, signing_key_ref text not null, revoked_at timestamptz, created_at timestamptz not null default now());
create table public.scans (id uuid primary key default gen_random_uuid(), org_id uuid not null references public.organizations(id) on delete cascade, location_id uuid not null references public.locations(id) on delete cascade, qr_id uuid not null references public.qr_codes(id) on delete restrict, scanned_at timestamptz not null default now(), source text not null default 'qr');
create table public.feedback (id uuid primary key default gen_random_uuid(), org_id uuid not null references public.organizations(id) on delete cascade, location_id uuid not null references public.locations(id) on delete cascade, qr_id uuid not null references public.qr_codes(id) on delete restrict, scan_id uuid references public.scans(id) on delete set null, rating smallint not null check(rating between 1 and 5), category text not null check(length(category) between 1 and 80), comment text not null default '' check(length(comment)<=1000), consent_version text not null, created_at timestamptz not null default now());
create index idx_locations_org on public.locations(org_id); create index idx_qr_org on public.qr_codes(org_id); create index idx_scans_org_time on public.scans(org_id,scanned_at desc); create index idx_feedback_org_time on public.feedback(org_id,created_at desc);
create function public.is_org_member(target_org uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.memberships m where m.org_id=target_org and m.user_id=auth.uid()); $$;
revoke all on function public.is_org_member(uuid) from public; grant execute on function public.is_org_member(uuid) to authenticated;
alter table public.organizations enable row level security; alter table public.memberships enable row level security; alter table public.locations enable row level security; alter table public.qr_codes enable row level security; alter table public.scans enable row level security; alter table public.feedback enable row level security;
create policy "members read own organizations" on public.organizations for select to authenticated using(public.is_org_member(id));
create policy "members read own memberships" on public.memberships for select to authenticated using(user_id=auth.uid() or public.is_org_member(org_id));
create policy "members manage own locations" on public.locations for all to authenticated using(public.is_org_member(org_id)) with check(public.is_org_member(org_id));
create policy "members manage own qr codes" on public.qr_codes for all to authenticated using(public.is_org_member(org_id)) with check(public.is_org_member(org_id));
create policy "members read own scans" on public.scans for select to authenticated using(public.is_org_member(org_id));
create policy "members read own feedback" on public.feedback for select to authenticated using(public.is_org_member(org_id));
revoke all on public.organizations,public.memberships,public.locations,public.qr_codes,public.scans,public.feedback from anon,authenticated;
grant select on public.organizations,public.memberships,public.scans,public.feedback to authenticated; grant select,insert,update,delete on public.locations,public.qr_codes to authenticated;
-- Scan and feedback writes reserved to the Edge Function service role after signature validation.
